/** A Duration represents a signed, fixed-length span of time represented as a count of seconds and fractions of seconds at nanosecond resolution. It is independent of any calendar and concepts like "day"… */
export interface Duration {
    /** Signed seconds of the span of time. Must be from -315,576,000,000 to +315,576,000,000 inclusive. Note: these bounds are computed from: 60 sec/min * 60 min/hr * 24 hr/day * 365.25 days/year * 10000 yea… */
    seconds: string;
    /** Signed fractions of a second at nanosecond resolution of the span of time. Durations less than one second are represented with a 0 `seconds` field and a positive or negative `nanos` field. For duratio… */
    nanos: number;
}

/** Represents civil time. */
export interface DateTime {
    /** Year of date. */
    year: number;
    /** Month of year. */
    month: number;
    /** Day of month. */
    day: number;
    /** Hours of day in 24 hour format. */
    hours: number;
    /** Minutes of hour of day. */
    minutes: number;
    /** Seconds of minutes of the time. */
    seconds: number;
    /** Fractions of seconds in nanoseconds. */
    nanos: number;
    /** UTC offset or time zone. */
    timeOffset: {
        oneofKind: "utcOffset";
        utcOffset: Duration;
    } | {
        oneofKind: "timeZone";
        timeZone: TimeZone;
    } | {
        oneofKind: undefined;
    };
}

/** Represents a time zone from the IANA Time Zone Database. */
export interface TimeZone {
    /** IANA Time Zone Database time zone. */
    id: string;
    /** IANA Time Zone Database version number. */
    version: string;
}
